    73→  @JsonCreator
    74→  public DataSchema(
    75→      @JsonProperty("dataSource") String dataSource,
    76→      @JsonProperty("timestampSpec") @Nullable TimestampSpec timestampSpec, // can be null in old task spec
    77→      @JsonProperty("dimensionsSpec") @Nullable DimensionsSpec dimensionsSpec, // can be null in old task spec
