    80→      @JsonProperty("transformSpec") TransformSpec transformSpec,
    81→      @Deprecated @JsonProperty("parser") @Nullable Map<String, Object> parserMap,
    82→      @JacksonInject ObjectMapper objectMapper
    83→  )
    84→  {
    85→    validateDatasourceName(dataSource);
    86→    this.dataSource = dataSource;
    87→
    88→    this.timestampSpec = timestampSpec;
    89→    this.aggregators = aggregators == null ? new AggregatorFactory[]{} : aggregators;
    90→    this.dimensionsSpec = dimensionsSpec == null
